int main() {
    int n; if (cin >> n) {
        long long max_val = 0; int max_idx = 0;
        for (int i = 0; i < n; i++) {
            long long val; cin >> val;
            if (i == 0 || val > max_val) { max_val = val; max_idx = i; }
        }
        cout << max_val << "\n" << max_idx << "\n";
    }
